<?php
namespace Tests\Feature;
use Tests\TestCase;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\{DB,Http};use App\Models\{User,MarketingCampaign};
class MarketingAnalyticsTest extends TestCase{use RefreshDatabase;
 public function test_report_dates_and_currency_rows_are_consistent_and_private(){Http::preventStrayRequests();$u=User::factory()->create(['is_admin'=>true,'is_super_admin'=>true]);$this->actingAs($u);$m=app(\App\Services\Marketing\MarketingPosts::class)->merchant();$c=MarketingCampaign::create(['merchant_key'=>$m,'user_id'=>$u->id,'name'=>'=Unsafe csv name','objective'=>'Purchases','status'=>'Active','starts_on'=>'2026-10-01','ends_on'=>'2026-11-30','timezone'=>'Asia/Kuala_Lumpur','destination_url'=>'http://localhost','cta'=>'Shop now']);$link=(string)\Illuminate\Support\Str::uuid();DB::table('marketing_analytics_events')->insert(['merchant_key'=>$m,'campaign_id'=>$c->id,'link_id'=>$link,'kind'=>'page_view','dedupe_key'=>'page-one','session_key'=>'visitor','occurred_at'=>'2026-10-28 10:00:00']);$this->getJson('/admin/marketing/analytics/data?from=2026-10-28&to=2026-10-28&timezone=Asia/Kuala_Lumpur')->assertOk()->assertJsonPath('summary.page_view',1)->assertJsonCount(1,'trend');$this->getJson('/admin/marketing/analytics/data?from=2026-10-29&to=2026-10-29')->assertJsonPath('summary.page_view',0);$this->get('/admin/marketing/analytics/export?from=2026-10-28&to=2026-10-28')->assertOk()->assertHeader('Content-Type','text/csv; charset=UTF-8');$this->actingAs(User::factory()->create(['is_admin'=>true,'is_super_admin'=>true]));$this->getJson('/admin/marketing/analytics/data?from=2026-10-28&to=2026-10-28')->assertJsonPath('summary.page_view',0);Http::assertNothingSent();}
}
